import{_ as a,o as n,c as t,an as o}from"./chunks/framework.DQcoBUS1.js";const u=JSON.parse('{"title":"Enzyme extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/enzyme.md","filePath":"extensions/enzyme.md","lastUpdated":null}'),r={name:"extensions/enzyme.md"};function s(i,e,d,c,l,p){return n(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="extension-enzyme" tabindex="-1">Enzyme extension <a class="header-anchor" href="#extension-enzyme" aria-label="Permalink to &quot;Enzyme extension {#extension-enzyme}&quot;">​</a></h1><p><code>ComposableRecurrencesEnzymeExt</code> is loaded automatically when Enzyme is available alongside ComposableRecurrences.</p><p>It registers the rule of every operator as an Enzyme reverse-mode rule. <a href="/dev/explanation/adjoints-and-backends#adjoint-routing">Rules and plain AD</a> says when a call takes the rule. It refuses <a href="/dev/lib/public#ComposableRecurrences.NoAdjoint"><code>NoAdjoint</code></a> on an active sparse coupling, where plain Enzyme reverse AD gives wrong gradients.</p><p>On Julia 1.11, an operator built in code that Julia cannot infer can get a zero Enzyme reverse gradient for its scalar float fields, such as <code>b</code> in <code>Add(b)</code> or the population of a <code>Depletion</code>. Uninferred code includes a closure that captures a variable it reassigns, or a call through a global that is not constant. Enzyme loses the gradient in that code, before any rule runs, so the extension cannot detect or refuse it. Instead it warns once per operator type, the first time Enzyme reverse mode differentiates an operator with an active scalar field on 1.11. Use Julia 1.12 or later, where Enzyme keeps these gradients, or build operators in type-stable code (check it with <code>@code_warntype</code>).</p>',4)])])}const h=a(r,[["render",s]]);export{u as __pageData,h as default};
